from lib import *
S = SS('t22')
steps = [
    step("三种角色各是一个独立进程:TC(状态存在自己的 tc_db 里)、账户 RM、库存 RM,TM 是实验脚本。一次成功的全局事务,从各进程的事件日志拼出来:14 ms TM 向 TC begin;账户 RM 向 TC 注册分支 1(28 ms)、申请全局锁(43 ms)、本地提交后报告 PHASE1_DONE(50 ms);库存 RM 同样走一遍(65 到 88 ms);95 ms TM 向 TC commit,TC 只把状态改成 COMMITTING 就返回,二阶段由 TC 的后台线程去做:124 ms、132 ms 依次调用两个 RM 的 branch_commit 删掉 undo_log,140 ms 全局事务 COMMITTED、全局锁释放。TM 的 commit 返回后 78 ms 事务才真正完成,账户 900、库存 47,undo_log 与全局锁都清空。", t=tl(S(1)), mark=lidx(S(1), 'TM → TC  commit', 'COMMITTING'), done=lidx(S(1), '→ COMMITTED', 'TM 的 commit 调用返回后'), b=bars([['TM begin(ms)', 14, '14'], ['TM commit(ms)', 95, '95'], ['全局事务 COMMITTED(ms)', 140, '140']], 150, cur=[0, 1], done=[2]), kv=KV([['TM', '决定 begin / commit / rollback'], ['RM', '本地分支 + 注册 + 报告 + 二阶段回调'], ['TC', '状态 + 全局锁 + 驱动二阶段']], ['TC'])),
    step("TM 崩溃:开了全局事务、做完两个分支就再也不来了(没有 commit 也没有 rollback)。两个分支做完时全局事务状态还是 BEGIN,账户 900、库存 47。TC 的超时扫描器接管:这里把全局事务超时设成 1.5 秒,1577 ms 时 TC 发现“一直没有收到 TM 的决定”,把状态改成 ROLLING_BACK,随后依次调用两个 RM 的 branch_rollback 按 undo_log 恢复,1607 ms 全局事务 ROLLED_BACK,账户恢复成 1000、库存 50,全局锁清空。没有人决定的事务,靠超时由 TC 回滚。", t=tl(S(2)), mark=lidx(S(2), '超时扫描'), done=lidx(S(2), '→ ROLLED_BACK', '开始后'), b=bars([['超时设置 ms', 1500, '1500'], ['TC 超时扫描触发 ms', 1577, '1577'], ['全局事务 ROLLED_BACK ms', 1607, '1607']], 1650, cur=[0], mark=[1], done=[2]), kv=KV([['TM 崩溃', '没有 commit / rollback'], ['TC 超时扫描', '到点就 ROLLING_BACK'], ['结果', '账户 1000、库存 50,恢复完成']], ['TC 超时扫描'])),
    step("TC 在二阶段中途被 kill -9,重启后从 tc_db 里恢复继续做。为了让崩溃发生在二阶段做完之前,先让两个 RM 的 branch_commit / branch_rollback 暂时失败。commit 一例:TC 被杀时状态是 COMMITTING,undo_log 还剩 1 + 1 行、全局锁 2 行;重启后 TC 的日志写着“启动恢复:库里有 1 个没做完二阶段的全局事务 COMMITTING,继续做”,219 ms 后两个分支都 branch_commit 成功(分支的尝试次数是第 4 次——被杀之前的失败次数还记在库里),状态 COMMITTED。rollback 一例同样:ROLLING_BACK 被杀,重启 10 ms 后做完,账户 1000、库存 50。TC 的状态都在库里,崩溃不丢决定。", t=tl(S(3)), mark=lidx(S(3), '被 kill -9 时', '启动恢复'), done=lidx(S(3), 'TC 重启后'), b=bars([['commit 恢复用时 ms', 219, '219'], ['rollback 恢复用时 ms', 10, '10'], ['恢复后 undo_log + 全局锁行数', 0, '0']], 230, cur=[0, 1], done=[2]), kv=KV([['TC 被杀', '状态 COMMITTING / ROLLING_BACK 在库里'], ['重启', '扫描库,继续没做完的二阶段'], ['分支尝试次数', '被杀前的失败次数也保留']], ['TC 被杀'])),
    step("RM 在二阶段暂时不可用:TC 带退避重试(100 ms 起、每次翻倍、上限 1.6 s)。先让账户 RM 的 branch_rollback 失败 3 次:TC 在 80 ms、186 ms、395 ms 失败(间隔 100、200、400 ms),第 4 次(815 ms)成功,全局事务 ROLLED_BACK,账户 1000、库存 50。再让它一直失败 4 秒:全局事务停在 ROLLING_BACK,TC 重试了 6 次,账户还是 900(分支已提交的 -100 还没恢复),全局锁仍有 2 行;另一个全局事务想改同一个账户,等了 1034 ms 后失败——没做完二阶段的事务一直占着全局锁。把故障去掉,TC 的下一次重试成功。", t=tl(S(4)), mark=lidx(S(4), '一直失败 4 秒', '另一个全局事务'), done=lidx(S(4), '下一次重试成功', '最终状态 ROLLED_BACK'), b=bars([['暂时失败 3 次:重试间隔 ms', 100, '100 → 200 → 400'], ['一直失败 4 秒:TC 重试次数', 6, '6'], ['别的事务等全局锁的 ms', 1034, '1034(失败)']], 1100, cur=[0, 1], mark=[2]), kv=KV([['暂时失败', '退避重试后成功'], ['一直失败', '停在 ROLLING_BACK,账户 900'], ['后果', '全局锁一直占着,别的事务被挡']], ['后果'])),
    step("每个全局事务产生多少次跨角色调用:单线程跑 50 个(每个 2 个分支),平均每个全局事务 TC 收到 begin 1、commit 1、register 2、lock 2、report 2,每个 RM 收到业务调用 1、branch_commit 1,合计 12.0 次 HTTP 调用(本地事务是 0 次),其中 TM 自己发起的只有 4 次。做完之后库里留下的:TC 的 global_tx 50 行(COMMITTED 历史)、branch 100 行,global_lock 0 行;RM 的 undo_log 0 + 0 行;TM 不存任何状态。这个原型的耗时(1 个 TM 线程 71.4 ms、4 个线程 90.9 ms、8 个线程 147.0 ms,每秒 14 / 42 / 53 个全局事务)主要是 Python 的 http.server 与每次新建连接造成的,只说明这个原型,不代表任何成熟的 TC。", t=tl(S(5)), mark=lidx(S(5), '合计每个全局事务'), done=lidx(S(5), '做完之后各角色库里'), b=bars([['每个全局事务的 HTTP 调用', 12, '12(本地事务 0 次)'], ['其中 TM 直接发起', 4, '4'], ['1 个 TM 线程:每秒全局事务', 14, '14'], ['8 个 TM 线程:每秒全局事务', 53, '53']], 55, cur=[0, 1], mark=[2, 3]), kv=KV([['HTTP 调用', '每个全局事务 12 次'], ['TC 留下', 'global_tx / branch 历史行'], ['耗时', '只代表这个 Python 原型']], ['HTTP 调用'])),
]
